import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../data/catalog_data.dart';import '../theme/app_theme.dart';import '../utils/friendly_error.dart';
class AccessoriesScreen extends StatefulWidget{const AccessoriesScreen({super.key});@override State<AccessoriesScreen> createState()=>_AccessoriesScreenState();}
class _AccessoriesScreenState extends State<AccessoriesScreen>{List<Map<String,dynamic>> _items=[];bool _loading=true;String _q='',_cat='الكل',_city='الكل';
Future<void> _load()async{try{var q=Supabase.instance.client.from('accessories').select('*').eq('status','active');if(_cat!='الكل')q=q.eq('category',_cat);if(_city!='الكل')q=q.eq('city',_city);final rows=await q.order('created_at',ascending:false);if(mounted)setState(()=>_items=List<Map<String,dynamic>>.from(rows));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(friendlyError(e,fallback:'تعذر تحميل الإكسسوارات.'))));}finally{if(mounted)setState(()=>_loading=false);}}
@override void initState(){super.initState();_load();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('إكسسوارات')),body:Column(children:[Padding(padding:const EdgeInsets.all(10),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'بحث'),onChanged:(v){_q=v.toLowerCase();setState((){});})),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[DropdownButton<String>(value:_cat,items:['الكل','جرابات','شواحن','شاشات','قطع غيار أخرى'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){_cat=v!;_load();}),const SizedBox(width:10),DropdownButton<String>(value:_city,items:['الكل',...CatalogData.cities].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){_city=v!;_load();})])),Expanded(child:_loading?const Center(child:CircularProgressIndicator(color:AppColors.gold)):_items.where((x)=>x['title'].toString().toLowerCase().contains(_q)).isEmpty?const Center(child:Text('لا توجد إكسسوارات')):ListView(children:_items.where((x)=>x['title'].toString().toLowerCase().contains(_q)).map((x)=>Card(child:ListTile(leading:(x['image_urls'] as List?)?.isNotEmpty==true?Image.network((x['image_urls'] as List).first,width:60,height:60,fit:BoxFit.cover):const Icon(Icons.inventory_2_outlined,color:AppColors.gold),title:Text(x['title']),subtitle:Text(x['city'].toString()),trailing:Text(x['price'].toString()+' ج.س',style:const TextStyle(color:AppColors.gold,fontWeight:FontWeight.bold)))).toList()) )]));
}